'use client'

import { useEffect, useState } from 'react'

interface MemexQueueButtonProps {
  alias?: string | null
  sourceUpdatedAt?: string | null
}

export const MemexQueueButton = ({
  alias,
  sourceUpdatedAt
}: MemexQueueButtonProps) => {
  const [pending, setPending] = useState(false)
  const [busy, setBusy] = useState(false)

  useEffect(() => {
    if (!alias) return

    let active = true

    void fetch(`/memex-queue?alias=${encodeURIComponent(alias)}`, {
      cache: 'no-store'
    })
      .then((response) => response.json())
      .then((data: { pending?: boolean }) => {
        if (active) setPending(Boolean(data.pending))
      })

    return () => {
      active = false
    }
  }, [alias])

  const toggle = async () => {
    if (!alias || busy) return

    setBusy(true)

    try {
      const response = await fetch('/memex-queue', {
        method: pending ? 'DELETE' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(
          pending
            ? { alias }
            : { alias, sourceUpdatedAt }
        )
      })

      if (!response.ok) {
        throw new Error(`Memex queue HTTP ${response.status}`)
      }

      const data = (await response.json()) as { pending?: boolean }
      setPending(Boolean(data.pending))
    } catch (error) {
      console.error('Memex queue update failed', error)
    } finally {
      setBusy(false)
    }
  }

  return (
    <button
      type='button'
      className={
        pending
          ? 'btn btn-sm btn-outline-danger ms-2'
          : 'btn btn-sm btn-outline-secondary ms-2'
      }
      disabled={!alias || busy}
      title={pending ? 'Remove from Memex queue' : 'Add to Memex queue'}
      onClick={() => void toggle()}>
      {busy ? 'Memex…' : pending ? '− Memex' : '+ Memex'}
    </button>
  )
}
